/**
 * Type declarations for Prism.js language components
 *
 * These modules are dynamically imported and don't have type declarations
 * in @types/prismjs. This file declares them as modules with no exports
 * since they register themselves with the global Prism object.
 */

declare module 'prismjs/components/prism-javascript' {
  // This module has side effects only - it registers the JavaScript grammar
}

declare module 'prismjs/components/prism-typescript' {
  // This module has side effects only - it registers the TypeScript grammar
}

declare module 'prismjs/components/prism-jsx' {
  // This module has side effects only - it registers the JSX grammar
}

declare module 'prismjs/components/prism-tsx' {
  // This module has side effects only - it registers the TSX grammar
}

declare module 'prismjs/components/prism-json' {
  // This module has side effects only - it registers the JSON grammar
}

declare module 'prismjs/components/prism-bash' {
  // This module has side effects only - it registers the Bash grammar
}

declare module 'prismjs/components/prism-css' {
  // This module has side effects only - it registers the CSS grammar
}

declare module 'prismjs/components/prism-markdown' {
  // This module has side effects only - it registers the Markdown grammar
}

declare module 'prismjs/components/prism-python' {
  // This module has side effects only - it registers the Python grammar
}
